import React from "react";
import { cn } from "@/src/utils/cn";

interface GlassPanelProps extends React.HTMLAttributes<HTMLDivElement> {
    children: React.ReactNode;
    variant?: "default" | "elevated" | "flat";
}

export function GlassPanel({
    children,
    className,
    variant = "default",
    ...props
}: GlassPanelProps) {
    return (
        <div
            className={cn(
                "rounded-2xl transition-all duration-300",
                variant === "default" && "bg-white/[0.03] backdrop-blur-xl border border-white/10 shadow-[0_8px_32px_rgba(0,0,0,0.2)]",
                variant === "elevated" && "bg-surface-elevated border border-white/10 shadow-lg",
                variant === "flat" && "bg-transparent border border-white/5",
                className
            )}
            {...props}
        >
            {children}
        </div>
    );
}
