"use client";

import { useState, useMemo } from "react";
import RecipeBuilder from "./RecipeBuilder";
import { GlassPanel } from "../../components/ui/GlassPanel";

interface AddProductModalProps {
  open: boolean;
  onClose: () => void;
  onSave: (payload: {
    productType: "simple" | "composite";
    name: string;
    unit: string;
    sellingPrice?: number;
    recipe?: any[];
  }) => Promise<void>;

  units?: string[];
  products?: any[];
}

export default function AddProductModal({
  open,
  onClose,
  onSave,
  units = [],
  products = [],
}: AddProductModalProps) {
  const [productType, setProductType] =
    useState<"simple" | "composite">("simple");
  const [name, setName] = useState("");
  const [unit, setUnit] = useState("");
  const [customUnit, setCustomUnit] = useState("");
  const [sellingPrice, setSellingPrice] = useState("");
  const [recipe, setRecipe] = useState<any[]>([]);

  if (!open) return null;

  const safeUnits = Array.isArray(units) ? units : [];
  const safeProducts = Array.isArray(products) ? products : [];

  const availableIngredients = useMemo(
    () => safeProducts.filter(p => !p?.isComposite),
    [safeProducts]
  );

  const canSave =
    name.trim() &&
    unit &&
    (productType === "simple" || recipe.length > 0);

  const handleCustomUnit = () => {
    const val = customUnit.trim();
    if (!val) return;
    setUnit(val);
    setCustomUnit("");
  };

  const handleSave = async () => {
    if (!canSave) return;

    await onSave({
      productType,
      name: name.trim(),
      unit,
      sellingPrice: sellingPrice
        ? Number(sellingPrice)
        : undefined,
      recipe:
        productType === "composite"
          ? recipe
          : undefined,
    });

    // reset state
    setName("");
    setUnit("");
    setCustomUnit("");
    setSellingPrice("");
    setRecipe([]);
    setProductType("simple");
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <GlassPanel variant="elevated" className="w-full max-w-lg overflow-hidden !p-0 border-white/10">

        {/* HEADER */}
        <div className="px-6 py-4 border-b border-white/10 bg-white/5">
          <h3 className="text-lg font-semibold text-foreground">
            Add New Product
          </h3>
        </div>

        {/* BODY */}
        <div className="p-6 space-y-5 max-h-[70vh] overflow-y-auto">

          {/* TYPE TOGGLE */}
          <div className="flex rounded-lg border border-white/10 overflow-hidden p-1 bg-white/5">
            {[
              { key: "simple", label: "Simple" },
              { key: "composite", label: "Composite" },
            ].map(t => (
              <button
                key={t.key}
                onClick={() =>
                  setProductType(t.key as any)
                }
                className={`flex-1 py-1.5 rounded-md text-sm font-medium transition-all
                  ${productType === t.key
                    ? "bg-primary text-background shadow-md"
                    : "text-muted hover:text-white hover:bg-white/5"
                  }`}
              >
                {t.label}
              </button>
            ))}
          </div>

          {/* NAME */}
          <input
            placeholder="Product name"
            value={name}
            onChange={e => setName(e.target.value)}
            className="h-11 w-full rounded-lg border border-white/10 bg-surface px-4 text-sm text-white placeholder:text-muted/50
            focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary"
          />

          {/* UNIT */}
          <select
            value={unit}
            onChange={e => setUnit(e.target.value)}
            className="h-11 w-full rounded-lg border border-white/10 bg-surface px-4 text-sm text-white focus:outline-none focus:ring-2 focus:ring-primary/50"
          >
            <option value="" className="bg-surface text-muted">Select unit</option>
            {safeUnits.map(u => (
              <option key={u} value={u} className="bg-surface text-white">
                {u}
              </option>
            ))}
          </select>

          {unit === "Custom" && (
            <input
              placeholder="Custom unit"
              value={customUnit}
              onChange={e => setCustomUnit(e.target.value)}
              onBlur={handleCustomUnit}
              className="h-11 w-full rounded-lg border border-white/10 bg-surface px-4 text-sm text-white placeholder:text-muted/50 focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          )}

          {/* PRICE */}
          <input
            type="number"
            placeholder="Selling price (optional)"
            value={sellingPrice}
            onChange={e => setSellingPrice(e.target.value)}
            className="h-11 w-full rounded-lg border border-white/10 bg-surface px-4 text-sm text-white placeholder:text-muted/50 focus:outline-none focus:ring-2 focus:ring-primary/50"
          />

          {/* RECIPE */}
          {productType === "composite" && (
            <div className="rounded-lg border border-white/10 p-4 bg-white/5">
              <RecipeBuilder
                products={availableIngredients}
                value={recipe}
                onChange={setRecipe}
              />
            </div>
          )}
        </div>

        {/* FOOTER */}
        <div className="px-6 py-4 border-t border-white/10 flex justify-end gap-3 bg-white/5">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg border border-white/10 text-sm hover:bg-white/5 text-muted hover:text-white transition-colors"
          >
            Cancel
          </button>

          <button
            disabled={!canSave}
            onClick={handleSave}
            className="px-5 py-2 rounded-lg bg-primary text-background
            font-semibold disabled:opacity-50 hover:bg-emerald-400 transition-colors"
          >
            Save Product
          </button>
        </div>
      </GlassPanel>
    </div>
  );
}
