"use client";

import { useState, useMemo } from "react";
import { X, Plus } from "lucide-react";

type Product = {
  _id: string;
  name: string;
  unit: string;
  purchasePrice?: number;
  isComposite?: boolean;
};

type RecipeItem = {
  productId: string;
  productName: string;
  unit: string;
  qtyRequired: number;
};

export default function RecipeBuilder({
  products = [],
  value = [],
  onChange,
}: {
  products?: Product[];
  value?: RecipeItem[];
  onChange: (items: RecipeItem[]) => void;
}) {
  const safeProducts = Array.isArray(products) ? products : [];
  const safeValue = Array.isArray(value) ? value : [];

  const [selectedProductId, setSelectedProductId] = useState("");
  const [qty, setQty] = useState("");

  const selectedProduct = useMemo(
    () => safeProducts.find(p => p._id === selectedProductId),
    [safeProducts, selectedProductId]
  );

  const addIngredient = () => {
    if (!selectedProduct) return;
    const amount = Number(qty);
    if (!amount || amount <= 0) return;

    if (safeValue.some(v => v.productId === selectedProduct._id)) return;

    onChange([
      ...safeValue,
      {
        productId: selectedProduct._id,
        productName: selectedProduct.name,
        unit: selectedProduct.unit,
        qtyRequired: amount,
      },
    ]);

    setSelectedProductId("");
    setQty("");
  };

  const removeIngredient = (id: string) => {
    onChange(safeValue.filter(v => v.productId !== id));
  };

  return (
    <div className="space-y-4">
      <h4 className="text-sm font-semibold text-foreground">
        Recipe (Ingredients)
      </h4>

      {/* ADD INGREDIENT */}
      <div className="grid grid-cols-12 gap-3 items-end">
        <div className="col-span-6">
          <label className="text-xs text-muted mb-1 block">
            Ingredient
          </label>
          <select
            value={selectedProductId}
            onChange={e => setSelectedProductId(e.target.value)}
            className="
              h-11 w-full rounded-lg border border-white/10
              bg-surface px-3 text-sm text-white
              focus:outline-none focus:ring-2 focus:ring-primary/50
            "
          >
            <option value="" className="bg-surface text-muted">Select product</option>
            {safeProducts.map(p => (
              <option key={p._id} value={p._id} className="bg-surface text-white">
                {p.name} ({p.unit})
              </option>
            ))}
          </select>
        </div>

        <div className="col-span-4">
          <label className="text-xs text-muted mb-1 block">
            Quantity {selectedProduct && `(${selectedProduct.unit})`}
          </label>
          <input
            type="number"
            min={0}
            step="any"
            value={qty}
            onChange={e => setQty(e.target.value)}
            placeholder="e.g. 2"
            className="
              h-11 w-full rounded-lg border border-white/10
              bg-surface px-3 text-sm text-white placeholder:text-muted/50
              focus:outline-none focus:ring-2 focus:ring-primary/50
            "
          />
        </div>

        <div className="col-span-2">
          <button
            onClick={addIngredient}
            disabled={!selectedProduct || !qty}
            className="
              h-11 w-full rounded-lg
              bg-primary text-background
              flex items-center justify-center
              hover:bg-emerald-400
              disabled:opacity-40
              transition-colors
            "
          >
            <Plus size={18} />
          </button>
        </div>
      </div>

      {/* INGREDIENT LIST */}
      {safeValue.length > 0 ? (
        <div className="rounded-lg border border-white/10 overflow-hidden">
          {safeValue.map(item => (
            <div
              key={item.productId}
              className="
                flex items-center justify-between
                px-4 py-3
                bg-white/5
                border-b border-white/5 last:border-none
              "
            >
              <div>
                <p className="text-sm font-medium text-foreground">
                  {item.productName}
                </p>
                <p className="text-xs text-muted">
                  {item.qtyRequired} {item.unit}
                </p>
              </div>

              <button
                onClick={() => removeIngredient(item.productId)}
                className="
                  h-8 w-8 rounded-md
                  flex items-center justify-center
                  text-muted
                  hover:text-rose-400
                  hover:bg-white/10
                  transition-colors
                "
              >
                <X size={14} />
              </button>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-xs text-muted">
          Add ingredients required to make this product
        </p>
      )}
    </div>
  );
}
